55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type PricedItemType = keyof typeof BASE_PREMIUMS;
69	
70	const hasBasePremium = (type: string): type is PricedItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  hasBasePremium(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	// A block is not carved out of a larger group: the block price applies only
87	// when the group consists of exactly three alike components (7 runes cost
88	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
89	// ever passes a single group from groupByType.
90	const isExactlyOneBlock = (group: Item[]): boolean =>
91	  group.length === BLOCK_SIZE;
92	
93	const sum = (amounts: number[]): number =>
94	  amounts.reduce((total, amount) => total + amount, 0);
95	
96	const sumBasePremiums = (items: Item[]): number =>
97	  sum(items.map(basePremiumForItem));
98	
99	// "Alike" means the same exact type, not merely the same family: two runes and
100	// a moonstone are three components but not three alike ones, so grouping them
101	// by type keeps them apart and denies them the block price.
102	const groupByType = (items: Item[]): Item[][] => {
103	  const groups = new Map<string, Item[]>();
104	  for (const item of items) {
105	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
106	  }
107	  return [...groups.values()];
108	};
109	
110	const basePremiumForGroup = (group: Item[]): number =>
111	  isExactlyOneBlock(group) ? BLOCK_BASE_PREMIUM : sumBasePremiums(group);
112	
113	const basePremiumForItems = (items: Item[]): number =>
114	  sum(groupByType(items).map(basePremiumForGroup));
115	
116	const CURSE_SURCHARGE = 0.5;
117	
118	// Every modifier is an additive percentage of its OWN base — modifiers never
119	// compound with each other. Item-scoped modifiers take the affected item's base
120	// premium as their base; policy-scoped modifiers take the policy base premium
121	// (the sum of all item base premiums). So the total is always
122	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
123	const modifierAmount = (rate: number, base: number): number => rate * base;
124	
125	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
126	
127	const HIGH_ENCHANTMENT_THRESHOLD = 5;
128	
129	const isCursed = (item: Item): boolean => item.cursed === true;
130	
131	const isHighlyEnchanted = (item: Item): boolean =>
132	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
133	
134	interface ItemModifier {
135	  rate: number;
136	  appliesTo: (item: Item) => boolean;
137	}
138	
139	// Each item-scoped modifier is a row: a rate and the condition under which it
140	// applies. The predicate names the modifier, so a row needs no separate label.
141	// Adding a modifier means adding a row, not a new branch.
142	const ITEM_MODIFIERS: ItemModifier[] = [
143	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
144	  { rate: HIGH_ENCHANTMENT_SURCHARGE, appliesTo: isHighlyEnchanted },
145	];
146	
147	const itemModifierRates = (item: Item): number[] =>
148	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
149	    (modifier) => modifier.rate,
150	  );
151	
152	const policyModifierRates = (): number[] => [INITIAL_ASSESSMENT_SURCHARGE];
153	
154	const itemModifiersTotal = (items: Item[]): number =>
155	  sum(
156	    items.flatMap((item) =>
157	      itemModifierRates(item).map((rate) =>
158	        modifierAmount(rate, basePremiumForItem(item)),
159	      ),
160	    ),
161	  );
162	
163	const policyModifiersTotal = (policyBasePremium: number): number =>
164	  sum(
165	    policyModifierRates().map((rate) =>
166	      modifierAmount(rate, policyBasePremium),
167	    ),
168	  );
169	
170	const quotePremium = (items: Item[]): number => {
171	  const policyBasePremium = basePremiumForItems(items);
172	  return Math.round(
173	    policyBasePremium +
174	      itemModifiersTotal(items) +
175	      policyModifiersTotal(policyBasePremium) +
176	      PROCESSING_FEE,
177	  );
178	};
179	
180	const runStep = (step: Step): StepResult => {
181	  if (step.op === "quote") return { premium: quotePremium(step.items) };
182	  throw new Error(`Unsupported step: ${step.op}`);
183	};
184	
185	export const runScenario = (scenario: Scenario): ScenarioResult => ({
186	  results: scenario.steps.map(runStep),
187	});
