// Policy-scoped modifiers are a flat list of rates rather than predicate rows:
// unlike item modifiers, they do not select per item. The list is kept even
// though it holds one rate today, because the loyalty and follow-up contract
// discounts join it unchanged.
const POLICY_MODIFIER_RATES: number[] = [INITIAL_ASSESSMENT_SURCHARGE];
